<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Http\Resources\VehicleResource;use App\Models\Vehicle;use Illuminate\Http\Request;
class VehicleController extends Controller { public function index(Request $r){$q=Vehicle::with(['brand','category','location','images','features'])->where('status','active')->when($r->category,fn($x,$v)=>$x->whereHas('category',fn($y)=>$y->where('name',$v)->orWhere('slug',$v)))->when($r->pickup_location,fn($x,$v)=>$x->whereHas('location',fn($y)=>$y->where('name',$v)->orWhere('slug',$v)))->when($r->search,fn($x,$v)=>$x->where(fn($y)=>$y->where('name','like',"%$v%")->orWhere('model','like',"%$v%")))->orderByDesc('featured')->orderBy('sort_order');return VehicleResource::collection($q->paginate(24));} public function featured(){return VehicleResource::collection(Vehicle::with(['brand','category','location','images','features'])->where('status','active')->where('featured',true)->orderBy('sort_order')->limit(8)->get());} public function show(string $slug){$v=Vehicle::with(['brand','category','location','images','features'])->where('slug',$slug)->orWhere('id',$slug)->firstOrFail();return new VehicleResource($v);} }
